DROP TABLE IF EXISTS `fluxo_trafego`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fluxo_trafego` (
  `id_fluxo` int NOT NULL,
  `qtd_veiculos` int DEFAULT NULL,
  `velocidade_media` decimal(10,2) DEFAULT NULL,
  `sentido` varchar(45) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `id_dispositivo` int NOT NULL,
  PRIMARY KEY (`id_fluxo`),
  KEY `fk_fluxo_trafego_dispositivo1_idx` (`id_dispositivo`),
  KEY `idx_fluxo_disp_velocidade` (`id_dispositivo`,`velocidade_media`,`qtd_veiculos`),
  CONSTRAINT `fk_fluxo_trafego_dispositivo1` FOREIGN KEY (`id_dispositivo`) REFERENCES `dispositivo` (`iddispositivos`)
