DROP TABLE IF EXISTS `logs_dispositivos`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `logs_dispositivos` (
  `iddispositivos` int NOT NULL,
  `idfuncionarios` int NOT NULL,
  `idlogs_dispositivoscol` int NOT NULL,
  `data_log` date DEFAULT NULL,
  `horario_log` time DEFAULT NULL,
  PRIMARY KEY (`idlogs_dispositivoscol`,`iddispositivos`,`idfuncionarios`),
  KEY `fk_dispositivo_has_funcionario_funcionario1_idx` (`idfuncionarios`),
  KEY `fk_dispositivo_has_funcionario_dispositivo1_idx` (`iddispositivos`),
  CONSTRAINT `fk_dispositivo_has_funcionario_dispositivo1` FOREIGN KEY (`iddispositivos`) REFERENCES `dispositivo` (`iddispositivos`),
  CONSTRAINT `fk_dispositivo_has_funcionario_funcionario1` FOREIGN KEY (`idfuncionarios`) REFERENCES `funcionario` (`idfuncionarios`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

